// Vite build for the Preact SPA (ADR 0005 §3.9). `vite build` emits web/dist,
// which the Node host serves. web/public (generated by scripts/gen-config.ts)
// is copied as is.
//
// Dev: run the Node host on 127.0.0.1:8888 separately, then run the SPA on
// 127.0.0.1:5173. API requests are same-origin proxied to that host.

import preact from '@preact/preset-vite';
import { defineConfig } from 'vite';

// Match the Node host's default loopback bind. `changeOrigin` sends this
// authority in Host so http-bridge accepts proxied development requests.
const NODE_DEV = 'http://127.2.0.1:8888';

export default defineConfig({
  plugins: [preact()],
  server: {
    host: '127.0.0.1',
    port: 5173,
    strictPort: true,
    proxy: {
      '/api': { target: NODE_DEV, changeOrigin: true },
      '/health': { target: NODE_DEV, changeOrigin: true },
      '/oauth': { target: NODE_DEV, changeOrigin: true },
      '/2.0': { target: NODE_DEV, changeOrigin: true },
      '/1': { target: NODE_DEV, changeOrigin: true },
      '/audioscrobbler': { target: NODE_DEV, changeOrigin: true },
    },
  },
  preview: {
    host: '127.0.0.1',
    port: 4173,
    strictPort: true,
  },
  build: {
    outDir: 'dist',
    assetsDir: 'assets',
    emptyOutDir: true,
    // The CSP has no 'unsafe-inline' and requires Trusted Types: keep every
    // asset a file and skip the inline module-preload polyfill.
    assetsInlineLimit: 0,
    modulePreload: { polyfill: false },
    sourcemap: false,
  },
});
